import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {resolve,join} from 'node:path';
import {createHash} from 'node:crypto';
import {runAnalysisDsl} from '../../../../src/analyze/run-analysis-dsl.ts';
const out=resolve('debugging/p6-p7-structural-gauges');await mkdir(out,{recursive:true});
const saved=JSON.parse(await readFile(join(out,'coupon.json'),'utf8'));
if(saved.runs[0].longitudinal.Ok?.status!=='complete')throw Error('Admitted coupon expected');
const scenario=await readFile('tests/fixtures/analysis-local-extraction/current-space/scenario.js','utf8');
const code='const candidate='+JSON.stringify(saved.runs[0])+';\n'+scenario;
const start=performance.now();
const result=await runAnalysisDsl({code},{filename:'p6-p7-structural-gauges.js',timeoutMs:120000,maxOutputBytes:8*1024*1024,maxEntries:2000});
await writeFile(join(out,'scenario.js'),code);
await writeFile(join(out,'dsl-result.json'),JSON.stringify({codeSha256:createHash('sha256').update(code).digest('hex'),wallMs:performance.now()-start,result}));
if(result.status!=='complete')throw Error(JSON.stringify(result.error));
const logs=result.reports.flatMap(r=>r.logs);
if(logs.filter(l=>l.message==='p6-p7.structural-gauge.complete').length!==2||!logs.some(l=>l.message==='p6-p7.structural-gauge.continued'))throw Error('Missing native/worker results or continuation');
const checks=result.reports.flatMap(r=>r.checks);
const plots=result.reports.flatMap(r=>r.plots) as Array<{kind?:string;data?:{kind?:string;values?:number[];axis?:{values?:number[]}}}>;
if(plots.length!==2||plots.some(p=>p.kind!=='line'||p.data?.kind!=='series'||p.data.values?.length!==17||JSON.stringify(p.data.axis?.values)!==JSON.stringify(saved.runs[0].sweep.map((s:{frequencyHz:number})=>s.frequencyHz))))throw Error('Missing two complete original-axis native response graph series');
console.log(JSON.stringify({status:result.status,completions:logs.filter(l=>l.message==='p6-p7.structural-gauge.complete'),checks,plotCount:plots.length,wallMs:performance.now()-start}));
